# Find hollow rectangular frames in input
def find_hollow_frames(grid, bg=8):
    """Find hollow rectangular frames of a given thickness=1"""
    frames = []
    h, w = len(grid), len(grid[0])
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg:
                continue
            # Check if this is part of a frame (on the boundary)
            color = grid[r][c]
            # For a hollow frame, boundary cells have the frame color, interior is bg
            # Find top-left of potential frame
            found = False
            for frame_r in range(max(0, r-5), r+1):
                for frame_c in range(max(0, c-5), c+1):
                    if frame_r >= h or frame_c >= w or grid[frame_r][frame_c] != color or grid[frame_r][frame_c] == bg:
                        continue
                    tr, tc = frame_r, frame_c
                    # Check if this forms a hollow frame
                    frame_height = r - frame_r + 1  # to current row should be left/top boundary
                    frame_width = c - frame_c + 1
                    # Check bottom and right boundaries
                    bottom_ok = tr + frame_height - 1 < h and tc + frame_width - 1 < w
                    interior_ok = tr + frame_height - 2 >= 0 and tc + frame_width - 2 >= 0
                    if bottom_ok and interior_ok:
                        # Check if interior is all background
                        interior_all_bg = True
                        for i in range(tr + 1, tr + frame_height - 1):
                            for j in range(tc + 1, tc + frame_width - 1):
                                if grid[i][j] != bg:
                                    interior_all_bg = False
                                    break
                            if not interior_all_bg:
                                break
                        if interior_all_bg:
                            # Check boundaries (top, bottom, left, right)
                            boundaries_ok = True
                            for j in range(tc, tc + frame_width):
                                if grid[tr][j] != color or grid[tr + frame_height - 1][j] != color:
                                    boundaries_ok = False
                                    break
                            for i in range(tr, tr + frame_height):
                                if grid[i][tc] != color or grid[i][tc + frame_width - 1] != color:
                                    boundaries_ok = False
                                    break
                            # Also need to check if frame is complete (not cut off by edge)
                            if boundaries_ok and tr > 0 and tc > 0 and tr + frame_height - 1 < h and tc + frame_width - 1 < w:
                                # Check frame doesn't touch edges (unless it's an edge frame)
                                if tr == 0 or tc == 0 or tr + frame_height - 1 == h-1 or tc + frame_width - 1 == w-1:
                                    continue
                                frames.append({
                                    'color': color,
                                    'top': tr, 'left': tc,
                                    'bottom': tr + frame_height - 1, 'right': tc + frame_width - 1
                                })
    return frames

